// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebasNeue = makeLoadFont('BebasNeue');
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: bebasFamily } = loadBebasNeue();
const { fontFamily: montserratFamily } = loadMontserrat();



export type WinnerPopupProps = Record<string, any>;

const WinnerPopup: React.FC<WinnerPopupProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 6,
  mainText = "WINNER!",
  subText = "MEGA JACKPOT",
  primaryColor = "#FFD700",
  secondaryColor = "#E60000",
  glowIntensity = 0.8,
  starCount = 16,
  rayCount = 18,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safe background logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const durationInFrames = Math.round(durationInSeconds * fps);
  const s = Math.min(width, height);

  // Animation timings
  const introSpring = spring({
    frame,
    fps,
    config: { damping: 10, mass: 1, stiffness: 100 },
  });

  const outroSpring = spring({
    frame: frame - (durationInFrames - 20),
    fps,
    config: { damping: 14, mass: 1, stiffness: 120 },
  });

  // Calculate master scale (intro goes 0->1, outro goes 0->1. We want 1->0 for outro)
  const masterScale = interpolate(outroSpring, [0, 1], [introSpring, 0]);

  // Subtext delayed entry
  const subIntroSpring = spring({
    frame: frame - 10,
    fps,
    config: { damping: 12, stiffness: 110 },
  });
  const subYOffset = interpolate(subIntroSpring, [0, 1], [s * 0.1, 0]);
  const subScale = interpolate(outroSpring, [0, 1], [subIntroSpring, 0]);

  // Pulsing glow effect
  const pulse = interpolate(Math.sin(frame * 0.15), [-1, 1], [0.6, 1.2]);
  const glowRadius = glowIntensity * 60 * pulse;

  // Background Rays
  const raysOpacity =
    interpolate(introSpring, [0, 0.5, 1], [0, 0, 0.2]) * (1 - outroSpring);
  
  const rays = Array.from({ length: rayCount }).map((_, i) => {
    const angle = (i / rayCount) * 180 + frame * 0.5;
    return (
      <div
        key={`ray-${i}`}
        style={{
          position: "absolute",
          width: "200%",
          height: s * 0.08,
          backgroundColor: secondaryColor,
          top: "50%",
          left: "-50%",
          transform: `translateY(-50%) rotate(${angle}deg)`,
          opacity: raysOpacity,
          transition: "none",
        }}
      />
    );
  });

  // Bursting Stars
  const stars = Array.from({ length: starCount }).map((_, i) => {
    const rand = random(i);
    const angle = (i / starCount) * Math.PI * 2 + frame * 0.005;
    const maxDist = (width * 0.4) * (0.5 + rand * 0.5);
    const dist = interpolate(introSpring, [0, 1], [0, maxDist]);
    const x = Math.cos(angle) * dist;
    const y = Math.sin(angle) * dist;
    
    // Twinkle effect based on index and frame
    const twinkle = interpolate(Math.sin(frame * 0.1 + i), [-1, 1], [0.4, 1]);
    const starScale = masterScale * twinkle * (0.5 + rand * 0.5);
    const rot = frame * (rand > 0.5 ? 2 : -2) + rand * 360;
    const starSize = s * 0.06;

    return (
      <div
        key={`star-${i}`}
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) translate(${x}px, ${y}px) scale(${starScale}) rotate(${rot}deg)`,
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 24 24"
          style={{
            width: starSize,
            height: starSize,
            fill: primaryColor,
            filter: `drop-shadow(0px 0px 8px ${primaryColor})`,
          }}
        >
          <path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" />
        </svg>
      </div>
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Background Layer: Rays & Stars */}
      <div style={{ position: "absolute", width: "100%", height: "100%" }}>
        {rays}
      </div>
      <div style={{ position: "absolute", width: "100%", height: "100%", zIndex: 1 }}>
        {stars}
      </div>

      {/* Center Layout for Text Elements */}
      <div
        style={{
          position: "relative",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 2,
          transition: "none",
        }}
      >
        {/* Main WINNER Text */}
        <div
          style={{
            fontFamily: bebasFamily,
            fontSize: width * 0.14,
            lineHeight: 1,
            color: primaryColor,
            textAlign: "center",
            WebkitTextStroke: `${Math.max(2, width * 0.003)}px ${secondaryColor}`,
            textShadow: `
              4px 4px 0px ${secondaryColor},
              8px 8px 0px #000,
              0px 0px ${glowRadius}px ${primaryColor}
            `,
            transform: `scale(${masterScale})`,
            zIndex: 3,
            position: "relative",
            transition: "none",
            letterSpacing: "0.05em",
          }}
        >
          {mainText}
        </div>

        {/* Subtext Badge */}
        {subText && (
          <div
            style={{
              fontFamily: montserratFamily,
              fontWeight: 900,
              fontSize: width * 0.03,
              color: "#FFFFFF",
              backgroundColor: secondaryColor,
              padding: `${width * 0.01}px ${width * 0.03}px`,
              borderRadius: width * 0.05,
              border: `${Math.max(2, width * 0.004)}px solid ${primaryColor}`,
              textTransform: "uppercase",
              letterSpacing: "0.1em",
              boxShadow: `0px ${width * 0.01}px ${width * 0.02}px rgba(0,0,0,0.6)`,
              textShadow: "2px 2px 0px rgba(0,0,0,0.4)",
              transform: `translateY(${subYOffset}px) scale(${subScale})`,
              marginTop: -(width * 0.02),
              zIndex: 2,
              transition: "none",
            }}
          >
            {subText}
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default WinnerPopup;